package com.kiwiplan.mes;

import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class PricingRuleEvaluator {
    // Evaluates a customer-supplied pricing formula as JavaScript.
    public double evaluate(String formula, double base) throws Exception {
        ScriptEngineManager mgr = new ScriptEngineManager();
        ScriptEngine engine = mgr.getEngineByName("nashorn"); // REMOVED in JDK 15
        engine.put("base", base);
        Object result = engine.eval(formula);
        return ((Number) result).doubleValue();
    }
}
